    # then a 5 ring, leaving gaps between outlines.
    for offset, color in ((1, 2), (2, 5), (4, 2), (5, 5), (7, 2), (8, 5), (10, 2), (11, 5)):
        r0, r1 = top + offset, bottom - offset
        c0, c1 = left + offset, right - offset
        if r0 > r1 or c0 > c1:
            continue
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color
    # Fill remaining central 2x2 patch in the large even test.
    center = (top + bottom) // 2
    if (bottom - top + 1) % 2 == 0 and (right - left + 1) % 2 == 0:
        for r in (center, center + 1):
            for c in (left + right) // 2, (left + right) // 2 + 1:
                out[r][c] = 2
    return out
